import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const c=JSON.parse('{"title":"Подарки и двусторонние сделки","description":"","frontmatter":{"pageId":"players/gifts-trades","contentRevision":2},"headers":[],"relativePath":"ru/players/gifts-trades.md","filePath":"ru/players/gifts-trades.md"}'),l={name:"ru/players/gifts-trades.md"};function o(s,a,n,d,h,p){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="подарки-и-двусторонние-сделки" tabindex="-1">Подарки и двусторонние сделки <a class="header-anchor" href="#подарки-и-двусторонние-сделки" aria-label="Permalink to &quot;Подарки и двусторонние сделки&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p><strong>Подарок:</strong> выбери игрока и содержимое передачи. Получатель принимает, отказывается или откладывает решение; отказ возвращает эскроу отправителю. По умолчанию неотвеченный подарок отклоняется через 7 дней. Флаг приёма подарков и блокировка влияют на новые предложения.</p><p><strong>Сделка:</strong> открой предложение, добавь вещи, пешек, серебро и заметку. Вторая сторона меняет свою часть. Любое изменение делает прежние подтверждения недействительными: обе стороны должны подтвердить одну и ту же ревизию. Отмена/истечение возвращает вклад владельцам. Проверь итоговый состав перед подтверждением.</p><p>После обрыва сначала обнови состояние сделки. Не отправляй те же вещи новым подарком, пока исход первой операции неизвестен.</p><h2 id="gift-flow" tabindex="-1">Подарок: отправка, решение и возврат <a class="header-anchor" href="#gift-flow" aria-label="Permalink to &quot;Подарок: отправка, решение и возврат {#gift-flow}&quot;">​</a></h2><p>В консоли связи открой «Отправить», выбери получателя, предметы/пешек из-под маяков и серебро из кошелька. Перепроверь имя и состав: отправленная пешка действительно покидает колонию. Дождись снимка и ответа, затем проверь состояние операции.</p><p>Получатель видит письмо: «Принять» разрешает капсулу; «Отказать» возвращает вещи отправителю, серебро — в его кошелёк; «Отложить» оставляет решение на потом. То же доступно в почте. Без решения подарок возвращается через неделю по умолчанию. Автоприём подарков — отдельная настройка; не путай её с согласием на сделки.</p><p>Блокировка не удаляет уже ожидающий подарок: его можно отклонить. Не отправляй второй экземпляр из-за того, что получатель сейчас офлайн.</p><h2 id="trade-flow" tabindex="-1">Двусторонняя сделка: что именно подтверждают обе стороны? <a class="header-anchor" href="#trade-flow" aria-label="Permalink to &quot;Двусторонняя сделка: что именно подтверждают обе стороны? {#trade-flow}&quot;">​</a></h2><ol><li>«Сделки» → «Новая сделка» либо «Торговать» у игрока с поселением. Офлайн-получатель допустим.</li><li>Добавь товары/пешек, серебро и заметку. Они удерживаются сервером, но до двух подтверждений обмена нет.</li><li>Партнёр меняет свою сторону. Сравни весь актуальный состав, а не только последнее сообщение.</li><li>«Изменить мою сторону» <strong>добавляет</strong> вещи. Для замены отметь возврат ранее предложенного: старое придёт почтой. Серебро и заметка задаются новыми итоговыми значениями.</li><li>После изменения другая сторона должна подтвердить новую ревизию. Если предложение успело измениться в открытом окне, старое подтверждение не принимается.</li><li>При двух подтверждениях одной версии стороны получают посылки. «Отменить» доступно обеим, возвращает каждую сторону её владельцу; истечение действует так же.</li></ol><p>Под угрозой или в долгу нельзя добавлять новый отток. Возврат, подтверждение и отмена остаются безопасными путями завершения. После обрыва сначала обнови ту же сделку.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>По умолчанию сделка живёт 7 дней, открытых сделок максимум 5. Закрытые сделки и запрет подарков — разные настройки. Никто не должен сообщать пароль для принятия передачи.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./economy">Кошелёк, почта и рынок</a></li><li><a href="./chat-pings">Чат, сообщения и пинги</a></li><li><a href="./saves-recovery">Сохранения и восстановление</a></li></ul>',17)])])}const u=e(l,[["render",o]]);export{c as __pageData,u as default};
